package org.sleepwell.app;

import android.app.Activity;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.View;
import android.widget.*;
import java.util.*;
import org.json.*;

/** Private in-screen draft. Only Save retains document access and changes the saved mix. */
final class SoundPlaylistEditor {
    static final int IMPORT=72;
    final Activity activity;private final Runnable finished;private final SharedPreferences preferences;
    private SoundMix previous;private SoundPlaylist draft=SoundPlaylist.EMPTY;private long revision;private String error="";private SoundImports.Job reading;private TextView progress;private boolean choosing;private final Map<String,Integer> offered=new HashMap<>();
    SoundPlaylistEditor(Activity activity,Bundle state,Runnable finished){this.activity=activity;this.finished=finished;preferences=SoundPreferences.factory.open(activity);try{previous=SoundPreferences.load(preferences).copy();draft=previous.playlist;revision=SoundPreferences.revision(preferences);if(state!=null){draft=SoundPlaylist.read(state.getString("tracks",""));revision=state.getLong("revision",revision);choosing=state.getBoolean("choosing");error=state.getString("error","");JSONObject flags=new JSONObject(state.getString("grants","{}"));if(flags.length()>SoundPlaylist.LIMIT)throw new IllegalArgumentException();for(Iterator<String> keys=flags.keys();keys.hasNext();){String key=keys.next();for(SoundPlaylist.Track track:draft.tracks)if(track.uri.equals(key))offered.put(key,flags.getInt(key));}String id=state.getString("reading");if(id!=null){reading=SoundImports.find(id);if(reading==null)error="The file check was interrupted. Choose that file again.";}}}catch(Exception invalid){previous=null;error="The saved mix or playlist could not be read. Return to Sleep sounds and choose a new mix.";}}
    Bundle state(){Bundle result=new Bundle();result.putBoolean("choosing",choosing);result.putString("tracks",draft.encode());result.putLong("revision",revision);result.putString("error",error);JSONObject flags=new JSONObject();try{for(Map.Entry<String,Integer> item:offered.entrySet())flags.put(item.getKey(),item.getValue());}catch(JSONException impossible){throw new IllegalStateException(impossible);}result.putString("grants",flags.toString());if(reading!=null)result.putString("reading",reading.id);return result;}
    boolean busy(){return reading!=null;}
    void render(){LinearLayout body=Design.page(activity,false,null,n->{});RecordUi.label(activity,body);RecordUi.header(body,"Local audio playlist",this::cancel);Design.space(body,12);Design.text(body,"Your files, in your order",25,600,Design.INK);Design.space(body,8);Design.text(body,"Up to eight readable audio documents, 100 MiB each. Files play once in order; the queue stops at its end or the mix timer, whichever comes first.",14,400,Design.MUTED);Design.space(body,16);
        if(previous==null){Design.text(body,error,14,500,Design.BROWN);Design.button(body,"Back",false,this::cancel);return;}
        if(draft.tracks.isEmpty())Design.text(body,"No playlist files selected",17,600,Design.MUTED);
        for(int i=0;i<draft.tracks.size();i++){int index=i;SoundPlaylist.Track track=draft.tracks.get(i);Design.item(body,"file",(i+1)+". "+track.title,String.format(Locale.ROOT,"%d:%02d · %.1f MiB",track.duration/60000,(track.duration/1000)%60,track.bytes/(1024d*1024)),()->{if(reading==null)options(index);});Design.line(body);}
        Design.space(body,12);Button add=Design.button(body,"Add audio file",false,this::choose);RecordUi.enabled(add,reading==null&&!choosing&&draft.tracks.size()<SoundPlaylist.LIMIT);
        if(reading!=null){progress=Design.text(body,"Checking audio…",13,500,Design.BROWN);Design.button(body,"Cancel file check",false,()->{stopReading();error="";render();});}else progress=null;
        if(!error.isEmpty()){Design.space(body,8);TextView message=Design.text(body,error,13,500,0xffa93919);message.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}
        Design.space(body,12);Design.text(body,"Save is silent and pauses the current mix. Return to Sleep sounds, then tap Play. Brown noise, timer and fade still apply across the whole queue. The original documents remain unchanged.",13,400,Design.MUTED);Design.space(body,8);Design.text(body,"Keep the document provider and files available. Revoked access or an unreadable track stops playback with an error; tracks are never silently skipped.",12,400,Design.MUTED);
        LinearLayout footer=RecordUi.footer(body);Button save=Design.button(footer,draft.tracks.isEmpty()?"Remove saved playlist":"Save playlist",true,this::save);RecordUi.enabled(save,reading==null&&!choosing);Design.button(footer,"Cancel",false,this::cancel);
    }
    private void options(int index){List<String> actions=new ArrayList<>();if(index>0)actions.add("Move up");if(index+1<draft.tracks.size())actions.add("Move down");actions.add("Remove from playlist");SleepPicker.choices(activity,"Track "+(index+1),actions.toArray(new String[0]),-1,choice->{if(reading!=null||choosing||index>=draft.tracks.size())return;String action=actions.get(choice);draft=action.equals("Move up")?draft.move(index,index-1):action.equals("Move down")?draft.move(index,index+1):draft.remove(index);offered.keySet().removeIf(uri->draft.tracks.stream().noneMatch(track->track.uri.equals(uri)));error="";render();});}
    private void choose(){if(reading!=null||choosing||draft.tracks.size()>=SoundPlaylist.LIMIT)return;try{choosing=true;activity.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION),IMPORT);}catch(RuntimeException missing){choosing=false;error="No audio document picker is available.";render();}}
    void result(int result,Intent data){choosing=false;if(result!=Activity.RESULT_OK){render();return;}if(reading!=null)return;try{if(data==null||data.getData()==null||data.getSelector()!=null)throw new IllegalArgumentException();Uri uri=data.getData();if(data.getClipData()!=null&&(data.getClipData().getItemCount()!=1||data.getClipData().getItemAt(0).getIntent()!=null||!uri.equals(data.getClipData().getItemAt(0).getUri())))throw new IllegalArgumentException();int flags=data.getFlags();int required=Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION;if((flags&required)!=required)throw new IllegalArgumentException();for(SoundPlaylist.Track track:draft.tracks)if(track.uri.equals(uri.toString()))throw new IllegalStateException("This file is already in the playlist.");reading=SoundImports.start(activity,uri,flags);error="";}catch(RuntimeException invalid){error=invalid instanceof IllegalStateException?invalid.getMessage():"Choose a readable audio document that offers persistent read access.";}render();}
    void poll(){if(reading==null)return;reading.poll();if(reading.state==SoundImports.State.READING){if(progress!=null)progress.setText("Checking audio · "+reading.bytes/1024+" KiB · up to 100 MiB");return;}SoundImports.Job job=reading;reading=null;try{if(job.state==SoundImports.State.READY){SoundPlaylist.Track track=job.playlistTrack();draft=draft.add(track);offered.put(track.uri,job.flags);error="";}else error=job.error.isEmpty()?"File check was cancelled.":job.error;}catch(RuntimeException invalid){error=invalid.getMessage()==null?"The file could not be added.":invalid.getMessage();}finally{job.retire();}render();}
    private void save(){if(reading!=null||choosing||previous==null)return;try{if(SoundPreferences.revision(preferences)!=revision)throw new IllegalStateException("The mix changed while this page was open. Cancel and reopen the playlist before saving.");
        Set<String> retained=new HashSet<>();for(android.content.UriPermission grant:activity.getContentResolver().getPersistedUriPermissions())if(grant.isReadPermission())retained.add(grant.getUri().toString());
        for(SoundPlaylist.Track track:draft.tracks){if(retained.contains(track.uri))continue;int required=Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION;if((offered.getOrDefault(track.uri,0)&required)!=required)throw new IllegalStateException("File access was lost. Remove and choose that file again before saving.");activity.getContentResolver().takePersistableUriPermission(Uri.parse(track.uri),Intent.FLAG_GRANT_READ_URI_PERMISSION);}
        SoundMix chosen=previous.copy();chosen.playlist=draft;if(!draft.tracks.isEmpty()){chosen.primary=SoundPlaylist.NAME;chosen.withTracking=false;}else if(chosen.primary.equals(SoundPlaylist.NAME)){chosen.primary="Rain";chosen.withTracking=false;}chosen.validate();SleepSoundService.pauseForSelection();if(!SoundPreferences.saveIfRevision(preferences,revision,chosen))throw new IllegalStateException("The mix changed. Cancel and reopen this page.");SoundPreferences.error(activity,"");SleepSoundService.update(activity);finished.run();
    }catch(RuntimeException failure){error=failure.getMessage()==null?"Playlist could not be saved. Your previous mix is unchanged.":failure.getMessage();render();}}
    private void stopReading(){SoundImports.Job job=reading;reading=null;if(job!=null){job.cancel();job.retire();}}
    void cancel(){choosing=false;stopReading();finished.run();}
    void destroy(boolean recreating){if(!recreating)stopReading();}
}
